  ["id"=>259, "topic"=>"Chemical Bonding", "question"=>"What is the color of permanganate ions (MnO4-) in water?", "answer"=>"Purple.", "difficulty"=>"easy"],
  ["id"=>260, "topic"=>"Chemical Bonding", "question"=>"What type of compound is formed when element X (Group II) reacts with element Y (Group VII)?", "answer"=>"An ionic compound with the formula XY2.", "difficulty"=>"medium"],
  ["id"=>261, "topic"=>"Chemical Bonding", "question"=>"Define relative molecular mass (Mr).", "answer"=>"The sum of the relative atomic masses of all the atoms present in a molecule.", "difficulty"=>"easy"],
  ["id"=>262, "topic"=>"Chemical Bonding", "question"=>"Calculate the formula mass of anhydrous calcium chloride (CaCl2). (Ar: Ca=40.1, Cl=35.5)", "answer"=>"40.1 + (35.5 * 2) = 111.1", "difficulty"=>"easy"],
  ["id"=>263, "topic"=>"Chemical Bonding", "question"=>"Why is quartz (SiO2) insoluble in water?", "answer"=>"Water molecules cannot break the strong covalent bonds holding the giant network structure together.", "difficulty"=>"hard"],
  ["id"=>264, "topic"=>"Chemical Bonding", "question"=>"What type of bond holds the atoms together inside a water molecule?", "answer"=>"Covalent bonds.", "difficulty"=>"easy"],
  ["id"=>265, "topic"=>"Chemical Bonding", "question"=>"What type of bond holds iodine molecules together in an iodine crystal?", "answer"=>"Weak van der Waals' forces (intermolecular forces).", "difficulty"=>"medium"],
  ["id"=>266, "topic"=>"Chemical Bonding", "question"=>"Why does molten sodium conduct electricity?", "answer"=>"Due to the presence of mobile delocalized electrons.", "difficulty"=>"medium"],
  ["id"=>267, "topic"=>"Chemical Bonding", "question"=>"Why is solid zinc a conductor but solid zinc chloride an insulator?", "answer"=>"Zinc has a metallic structure with mobile electrons. Zinc chloride is an ionic solid with no mobile ions or electrons.", "difficulty"=>"hard"],
  ["id"=>268, "topic"=>"Chemical Bonding", "question"=>"How many shared pairs of electrons form a double covalent bond?", "answer"=>"Two pairs (4 electrons total).", "difficulty"=>"easy"],
  ["id"=>269, "topic"=>"Chemical Bonding", "question"=>"Name a diatomic gas that contains a triple covalent bond.", "answer"=>"Nitrogen gas (N2).", "difficulty"=>"medium"],
  ["id"=>270, "topic"=>"Chemical Bonding", "question"=>"What is the shape and structure of a buckminsterfullerene (C60) molecule?", "answer"=>"A simple molecular structure with a hollow sphere shape.", "difficulty"=>"hard"],
  ["id"=>271, "topic"=>"Chemical Bonding", "question"=>"Define formula mass.", "answer"=>"The mass of one formula unit of an ionic compound compared to 1/12th the mass of a carbon-12 atom.", "difficulty"=>"easy"],

