  ["id"=>301, "topic"=>"Extraction of Metals", "question"=>"Name one metal found in nature in its free/uncombined elemental state.", "answer"=>"Gold or Platinum.", "difficulty"=>"easy"],
  ["id"=>302, "topic"=>"Extraction of Metals", "question"=>"What general chemical process converts a metal ion in an ore into a neutral metal atom?", "answer"=>"Reduction (gain of electrons).", "difficulty"=>"medium"],
  ["id"=>303, "topic"=>"Extraction of Metals", "question"=>"What reducing agent is most commonly used to extract iron from hematite in industry?", "answer"=>"Carbon monoxide (CO) derived from coke.", "difficulty"=>"hard"],
  ["id"=>304, "topic"=>"Extraction of Metals", "question"=>"Why must electrolysis be performed on molten ores rather than aqueous solutions to extract sodium?", "answer"=>"Water would be preferentially reduced at the cathode, producing hydrogen gas instead of sodium metal.", "difficulty"=>"hard"],
  ["id"=>305, "topic"=>"Extraction of Metals", "question"=>"Why are metal reserves considered finite resources?", "answer"=>"The earth has a fixed supply of ores, which cannot be replenished once consumed.", "difficulty"=>"easy"],
  ["id"=>306, "topic"=>"Extraction of Metals", "question"=>"State one environmental benefit of recycling aluminum.", "answer"=>"It saves habitat from mining and requires less energy than extracting it from bauxite.", "difficulty"=>"medium"],
  ["id"=>307, "topic"=>"Extraction of Metals", "question"=>"State one economic benefit of recycling metals.", "answer"=>"It lowers production costs because recycling requires less energy than primary extraction.", "difficulty"=>"medium"],
  ["id"=>308, "topic"=>"Reactivity of Metals", "question"=>"Describe the observation when a small piece of sodium is added to water.", "answer"=>"It melts into a silvery ball, floats, moves rapidly on the surface with a hissing sound, and eventually disappears.", "difficulty"=>"medium"],
  ["id"=>309, "topic"=>"Reactivity of Metals", "question"=>"What gas is produced when an active metal reacts with cold water?", "answer"=>"Hydrogen gas.", "difficulty"=>"easy"],
  ["id"=>310, "topic"=>"Reactivity of Metals", "question"=>"Write the balanced equation for the reaction of Calcium with cold water.", "answer"=>"Ca(s) + 2H2O(l) -> Ca(OH)2(s/aq) + H2(g)", "difficulty"=>"medium"],
  ["id"=>311, "topic"=>"Reactivity of Metals", "question"=>"Does Magnesium react rapidly with cold water?", "answer"=>"No, it reacts very slowly with cold water, but reacts vigorously with steam.", "difficulty"=>"medium"],
  ["id"=>312, "topic"=>"Reactivity of Metals", "question"=>"What are the products when Magnesium reacts with steam?", "answer"=>"Magnesium oxide (MgO) white powder and hydrogen gas.", "difficulty"=>"hard"],
  ["id"=>313, "topic"=>"Reactivity of Metals", "question"=>"Write the balanced equation for the reaction of Magnesium with steam.", "answer"=>"Mg(s) + H2O(g) -> MgO(s) + H2(g)", "difficulty"=>"hard"],
  ["id"=>314, "topic"=>"Reactivity of Metals", "question"=>"Do Zinc and Iron react with cold water?", "answer"=>"No, they only react when heated with steam.", "difficulty"=>"medium"],
  ["id"=>315, "topic"=>"Reactivity of Metals", "question"=>"Does Copper react with dilute hydrochloric acid?", "answer"=>"No, it is below hydrogen in the reactivity series.", "difficulty"=>"easy"],
  ["id"=>316, "topic"=>"Reactivity of Metals", "question"=>"State the general word equation for the reaction between a metal and a dilute acid.", "answer"=>"Metal + Dilute Acid -> Salt + Hydrogen gas", "difficulty"=>"easy"],
  ["id"=>317, "topic"=>"Reactivity of Metals", "question"=>"Write the balanced molecular equation for Zinc reacting with dilute sulphuric acid.", "answer"=>"Zn(s) + H2SO4(aq) -> ZnSO4(aq) + H2(g)", "difficulty"=>"medium"],
  ["id"=>318, "topic"=>"Reactivity of Metals", "question"=>"Write the ionic equation for the reaction of Iron with dilute hydrochloric acid.", "answer"=>"Fe(s) + 2H+(aq) -> Fe2+(aq) + H2(g)", "difficulty"=>"hard"],
  ["id"=>319, "topic"=>"Reactivity of Metals", "question"=>"List the metal reactivity series from Potassium down to Copper.", "answer"=>"K, Na, Ca, Mg, Al, Zn, Fe, Pb, (H), Cu.", "difficulty"=>"medium"],
  ["id"=>320, "topic"=>"Reactivity of Metals", "question"=>"Define a metal displacement reaction.", "answer"=>"A reaction where a more reactive metal displaces a less reactive metal from its salt solution.", "difficulty"=>"medium"],
  ["id"=>321, "topic"=>"Reactivity of Metals", "question"=>"What is observed when a piece of zinc is placed in copper(II) sulphate solution?", "answer"=>"The blue solution fades, a reddish-brown solid deposits on the zinc, and the zinc dissolves.", "difficulty"=>"medium"],
  ["id"=>322, "topic"=>"Reactivity of Metals", "question"=>"Write the ionic equation for the displacement of copper by zinc.", "answer"=>"Zn(s) + Cu2+(aq) -> Zn2+(aq) + Cu(s)", "difficulty"=>"medium"],
  ["id"=>323, "topic"=>"Reactivity of Metals", "question"=>"What happens if a copper wire is dipped into zinc sulphate solution?", "answer"=>"No reaction occurs because copper is less reactive than zinc.", "difficulty"=>"easy"],
  ["id"=>324, "topic"=>"Reactivity of Metals", "question"=>"Why does sodium have a higher tendency to form positive ions than magnesium?", "answer"=>"Sodium only needs to lose 1 valence electron, requiring less total ionization energy than magnesium, which must lose 2.", "difficulty"=>"hard"],
  ["id"=>325, "topic"=>"Quantitative Chemistry", "question"=>"Define the mole.", "answer"=>"The amount of substance that contains as many elementary entities as there are atoms in exactly 12g of carbon-12.", "difficulty"=>"medium"],
  ["id"=>326, "topic"=>"Quantitative Chemistry", "question"=>"What is the numerical value of Avogadro's constant (L)?", "answer"=>"6.02 * 10^23 mol^-1", "difficulty"=>"easy"],
  ["id"=>327, "topic"=>"Quantitative Chemistry", "question"=>"State the formula connecting number of moles, mass, and molar mass.", "answer"=>"Number of moles = Mass (g) / Molar Mass (g/mol)", "difficulty"=>"easy"],
  ["id"=>328, "topic"=>"Quantitative Chemistry", "question"=>"Calculate the mass of 0.5 moles of water (H2O). (H=1.0, O=16.0)", "answer"=>"0.5 * (2 + 16) = 9.0 grams.", "difficulty"=>"easy"],
  ["id"=>329, "topic"=>"Quantitative Chemistry", "question"=>"How many molecules are present in 2.0 moles of carbon dioxide?", "answer"=>"2.0 * 6.02 * 10^23 = 1.204 * 10^24 molecules.", "difficulty"=>"medium"],
  ["id"=>330, "topic"=>"Quantitative Chemistry", "question"=>"Define empirical formula.", "answer"=>"The simplest whole-number ratio of atoms of each element present in a compound.", "difficulty"=>"medium"],
  ["id"=>331, "topic"=>"Quantitative Chemistry", "question"=>"Define molecular formula.", "answer"=>"The actual number of atoms of each element present in a molecule of a compound.", "difficulty"=>"medium"],
  ["id"=>332, "topic"=>"Quantitative Chemistry", "question"=>"A compound contains 40.0% Ca, 12.0% C, and 48.0% O by mass. Determine its empirical formula.", "answer"=>"Mol ratio Ca:C:O = 40/40 : 12/12 : 48/16 = 1 : 1 : 3. Formula is CaCO3.", "difficulty"=>"medium"],
  ["id"=>333, "topic"=>"Quantitative Chemistry", "question"=>"What is a limiting reagent?", "answer"=>"The reactant that is completely consumed in a chemical reaction and limits the amount of product formed.", "difficulty"=>"medium"],
  ["id"=>334, "topic"=>"Quantitative Chemistry", "question"=>"If 1 mole of Mg reacts with 3 moles of HCl via Mg + 2HCl -> MgCl2 + H2, which is the limiting reagent?", "answer"=>"Mg is limiting (requires 2 moles of HCl, leaving 1 mole of HCl in excess).", "difficulty"=>"hard"],
  ["id"=>335, "topic"=>"Quantitative Chemistry", "question"=>"Calculate the percentage by mass of Iron in Fe2O3. (Fe=55.8, O=16.0)", "answer"=>"Molar mass = 159.6. % Fe = (111.6 / 159.6) * 100% = 69.9%.", "difficulty"=>"medium"],
  ["id"=>336, "topic"=>"Corrosion and Protection", "question"=>"What is the chemical name and composition of iron rust?", "answer"=>"Hydrated iron(III) oxide, Fe2O3 • nH2O.", "difficulty"=>"medium"],
  ["id"=>337, "topic"=>"Corrosion and Protection", "question"=>"What two substances are essential for the rusting of iron?", "answer"=>"Oxygen and water.", "difficulty"=>"easy"],
  ["id"=>338, "topic"=>"Corrosion and Protection", "question"=>"Name two common solutes that accelerate the rate of iron rusting.", "answer"=>"Sodium chloride (salts) and acidic pollutants (acids).", "difficulty"=>"medium"],
  ["id"=>339, "topic"=>"Corrosion and Protection", "question"=>"What components make up rust indicator solution?", "answer"=>"Potassium hexacyanoferrate(III) and phenolphthalein.", "difficulty"=>"hard"],
  ["id"=>340, "topic"=>"Corrosion and Protection", "question"=>"What color change indicates the presence of iron(II) ions when using rust indicator?", "answer"=>"It turns blue.", "difficulty"=>"hard"],
  ["id"=>341, "topic"=>"Corrosion and Protection", "question"=>"What color change occurs in rust indicator when hydroxide ions are produced?", "answer"=>"It turns pink.", "difficulty"=>"hard"],
  ["id"=>342, "topic"=>"Corrosion and Protection", "question"=>"How does painting prevent iron from rusting?", "answer"=>"It provides a protective barrier layer that excludes oxygen and water.", "difficulty"=>"easy"],
  ["id"=>343, "topic"=>"Corrosion and Protection", "question"=>"What is galvanizing?", "answer"=>"Coating iron with a layer of zinc.", "difficulty"=>"medium"],
  ["id"=>344, "topic"=>"Corrosion and Protection", "question"=>"Why does galvanized iron resist rust even if the zinc layer is scratched?", "answer"=>"Zinc is more reactive than iron, so it acts as a sacrificial anode and corrodes preferentially.", "difficulty"=>"hard"],
  ["id"=>345, "topic"=>"Corrosion and Protection", "question"=>"What is tin-plating?", "answer"=>"Coating iron with a layer of less reactive tin.", "difficulty"=>"medium"],
  ["id"=>346, "topic"=>"Corrosion and Protection", "question"=>"What happens if the tin layer on a tin-plated food can is scratched?", "answer"=>"The iron rusts faster than normal because iron is more reactive than tin and undergoes accelerated corrosion.", "difficulty"=>"hard"],
  ["id"=>347, "topic"=>"Corrosion and Protection", "question"=>"Define sacrificial protection.", "answer"=>"Protecting a metal from corrosion by connecting it to a more reactive metal that oxidizes preferentially.", "difficulty"=>"medium"],
  ["id"=>348, "topic"=>"Corrosion and Protection", "question"=>"Give an example of sacrificial protection used on marine vessels.", "answer"=>"Attaching zinc blocks to the steel hulls of ships.", "difficulty"=>"medium"],
  ["id"=>349, "topic"=>"Corrosion and Protection", "question"=>"What is cathodic protection?", "answer"=>"Connecting the metal to the negative terminal of an external DC power source to supply electrons and prevent oxidation.", "difficulty"=>"hard"],
  ["id"=>350, "topic"=>"Corrosion and Protection", "question"=>"What alloy is created by adding chromium and nickel to iron to prevent rust?", "answer"=>"Stainless steel.", "difficulty"=>"medium"],
  ["id"=>351, "topic"=>"Corrosion and Protection", "question"=>"Why is aluminum highly corrosion-resistant despite being a reactive metal?", "answer"=>"It reacts rapidly with oxygen in the air to form a tough, impermeable layer of aluminum oxide (Al2O3) that prevents further reaction.", "difficulty"=>"medium"],
  ["id"=>352, "topic"=>"Corrosion and Protection", "question"=>"What industrial process artificially thickens the protective oxide layer on aluminum?", "answer"=>"Anodization.", "difficulty"=>"medium"],
  ["id"=>353, "topic"=>"Corrosion and Protection", "question"=>"During aluminum anodization, is the aluminum object placed at the anode or cathode?", "answer"=>"At the anode (where oxygen gas is released to oxidize the aluminum surface).", "difficulty"=>"hard"],
  ["id"=>354, "topic"=>"Corrosion and Protection", "question"=>"What electrolyte is typically used in the anodization of aluminum?", "answer"=>"Dilute sulphuric acid.", "difficulty"=>"hard"],
  ["id"=>355, "topic"=>"Corrosion and Protection", "question"=>"State one daily use of anodized aluminum.", "answer"=>"Window frames, sports equipment, or cookware.", "difficulty"=>"easy"],
  ["id"=>356, "topic"=>"Extraction of Metals", "question"=>"What is the purpose of adding limestone to the blast furnace?", "answer"=>"To remove silica impurities by forming molten slag (calcium silicate).", "difficulty"=>"hard"],
  ["id"=>357, "topic"=>"Extraction of Metals", "question"=>"Write the chemical equation for the reduction of hematite by carbon monoxide.", "answer"=>"Fe2O3(s) + 3CO(g) -> 2Fe(l) + 3CO2(g)", "difficulty"=>"hard"],
  ["id"=>358, "topic"=>"Reactivity of Metals", "question"=>"Why is lead less reactive than iron in reactions with dilute acids?", "answer"=>"It forms an insoluble lead(II) chloride or lead(II) sulphate coating that prevents further reaction.", "difficulty"=>"hard"],
  ["id"=>359, "topic"=>"Quantitative Chemistry", "question"=>"State the volume occupied by one mole of any gas at room temperature and pressure (RTP).", "answer"=>"24.0 dm^3 (or 24000 cm^3).", "difficulty"=>"medium"],
  ["id"=>360, "topic"=>"Corrosion and Protection", "question"=>"What kind of bond structure gives the anodized Al2O3 layer its high hardness?", "answer"=>"A giant ionic structure.", "difficulty"=>"hard"],
  ["id"=>361, "topic"=>"Quantitative Chemistry", "question"=>"What is the percentage by mass of oxygen in water?", "answer"=>"(16 / 18) * 100% = 88.9%.", "difficulty"=>"easy"],
  ["id"=>362, "topic"=>"Quantitative Chemistry", "question"=>"Convert 0.25 moles of sodium hydroxide into grams.", "answer"=>"0.25 * 40.0 = 10.0 grams.", "difficulty"=>"easy"],
  ["id"=>363, "topic"=>"Reactivity of Metals", "question"=>"What color is zinc oxide when hot and cold?", "answer"=>"Yellow when hot, white when cold.", "difficulty"=>"medium"],
  ["id"=>364, "topic"=>"Reactivity of Metals", "question"=>"What color is copper(II) oxide?", "answer"=>"Black.", "difficulty"=>"easy"],
  ["id"=>365, "topic"=>"Quantitative Chemistry", "question"=>"How many total atoms are present in 1 mole of ammonia (NH3) gas?", "answer"=>"4 * 6.02 * 10^23 = 2.408 * 10^24 atoms.", "difficulty"=>"medium"],
  ["id"=>366, "topic"=>"Reactivity of Metals", "question"=>"Does gold react with oxygen when heated?", "answer"=>"No, it remains bright and shiny.", "difficulty"=>"easy"],
  ["id"=>367, "topic"=>"Corrosion and Protection", "question"=>"Why does salting roads in winter accelerate car chassis rusting?", "answer"=>"The salt dissolves in water to form an electrolyte solution, increasing electrical conductivity and accelerating electrochemical corrosion.", "difficulty"=>"hard"],
  ["id"=>368, "topic"=>"Reactivity of Metals", "question"=>"What is the chemical name for the reaction where a substance loses electrons?", "answer"=>"Oxidation.", "difficulty"=>"easy"],
  ["id"=>369, "topic"=>"Reactivity of Metals", "question"=>"What is the chemical name for the reaction where a substance gains electrons?", "answer"=>"Reduction.", "difficulty"=>"easy"],
  ["id"=>370, "topic"=>"Quantitative Chemistry", "question"=>"If the empirical formula of a gas is CH2 and its molar mass is 56.0 g/mol, what is its molecular formula?", "answer"=>"Empirical mass = 14. 56 / 14 = 4. Molecular formula is C4H8.", "difficulty"=>"medium"],
  ["id"=>371, "topic"=>"Extraction of Metals", "question"=>"What role does cryolite play in the extraction of aluminium?", "answer"=>"It dissolves the aluminium oxide, lowering the melting point from 2000°C to 950°C to reduce energy costs.", "difficulty"=>"hard"],
  ["id"=>372, "topic"=>"Corrosion and Protection", "question"=>"Can scratch-damaged tin-plated iron safely be used for food storage?", "answer"=>"No, the iron will rust faster once exposed, contaminating the food container.", "difficulty"=>"medium"],

