  ["id"=>401, "topic"=>"Introduction to Acids", "question"=>"Name a household acid found in lemons.", "answer"=>"Citric acid.", "difficulty"=>"easy"],
  ["id"=>402, "topic"=>"Introduction to Acids", "question"=>"What acid is found in household vinegar?", "answer"=>"Ethanoic acid (acetic acid).", "difficulty"=>"easy"],
  ["id"=>403, "topic"=>"Introduction to Acids", "question"=>"Name two common strong mineral acids used in the laboratory.", "answer"=>"Hydrochloric acid (HCl) and Sulphuric acid (H2SO4).", "difficulty"=>"easy"],
  ["id"=>404, "topic"=>"Introduction to Acids", "question"=>"What ion is responsible for all typical acidic properties in aqueous solutions?", "answer"=>"Hydrogen ion (H+ or hydronium H3O+).", "difficulty"=>"easy"],
  ["id"=>405, "topic"=>"Introduction to Acids", "question"=>"Why does dry citric acid solid not turn blue litmus paper red?", "answer"=>"In the absence of water, it cannot dissociate to release free H+ ions, which are required to exhibit acidic properties.", "difficulty"=>"medium"],
  ["id"=>406, "topic"=>"Introduction to Acids", "question"=>"Define the basicity of an acid.", "answer"=>"The maximum number of moles of hydrogen ions that can be produced by the complete ionization of one mole of the acid.", "difficulty"=>"medium"],
  ["id"=>407, "topic"=>"Introduction to Acids", "question"=>"State the basicity of Hydrochloric acid (HCl).", "answer"=>"Monobasic.", "difficulty"=>"easy"],
  ["id"=>408, "topic"=>"Introduction to Acids", "question"=>"State the basicity of Sulphuric acid (H2SO4).", "answer"=>"Dibasic.", "difficulty"=>"easy"],
  ["id"=>409, "topic"=>"Introduction to Acids", "question"=>"State the basicity of Phosphoric acid (H3PO4).", "answer"=>"Tribasic.", "difficulty"=>"easy"],
  ["id"=>410, "topic"=>"Introduction to Acids", "question"=>"State the basicity of Ethanoic acid (CH3COOH). Why?", "answer"=>"Monobasic, because only the single hydrogen atom in the carboxyl group (-COOH) can ionize.", "difficulty"=>"medium"],
  ["id"=>411, "topic"=>"Introduction to Acids", "question"=>"State the general word equation for the reaction of an acid with a metal carbonate.", "answer"=>"Acid + Metal Carbonate -> Salt + Water + Carbon Dioxide", "difficulty"=>"easy"],
  ["id"=>412, "topic"=>"Introduction to Acids", "question"=>"State the general word equation for the reaction of an acid with a metal hydrogencarbonate.", "answer"=>"Acid + Metal Hydrogencarbonate -> Salt + Water + Carbon Dioxide", "difficulty"=>"easy"],
  ["id"=>413, "topic"=>"Introduction to Acids", "question"=>"Write the ionic equation for the reaction between any dilute acid and a soluble carbonate solution.", "answer"=>"CO32-(aq) + 2H+(aq) -> H2O(l) + CO2(g)", "difficulty"=>"medium"],
  ["id"=>414, "topic"=>"Introduction to Acids", "question"=>"State the general word equation for the reaction of an acid with a base.", "answer"=>"Acid + Base -> Salt + Water", "difficulty"=>"easy"],
  ["id"=>415, "topic"=>"Introduction to Bases", "question"=>"Define a base.", "answer"=>"A metal oxide or metal hydroxide that reacts with an acid to form a salt and water only.", "difficulty"=>"medium"],
  ["id"=>416, "topic"=>"Introduction to Bases", "question"=>"What is an alkali?", "answer"=>"A water-soluble base.", "difficulty"=>"easy"],
  ["id"=>417, "topic"=>"Introduction to Bases", "question"=>"Name two common laboratory alkalis.", "answer"=>"Sodium hydroxide (NaOH) and Aqueous ammonia (NH3).", "difficulty"=>"easy"],
  ["id"=>418, "topic"=>"Introduction to Bases", "question"=>"What ion is responsible for all typical alkaline properties in aqueous solutions?", "answer"=>"Hydroxide ion (OH-).", "difficulty"=>"easy"],
  ["id"=>419, "topic"=>"Introduction to Bases", "question"=>"What gas is liberated when an alkali is heated with an ammonium salt?", "answer"=>"Ammonia gas (NH3).", "difficulty"=>"medium"],
  ["id"=>420, "topic"=>"Introduction to Bases", "question"=>"What chemical test is used to detect ammonia gas?", "answer"=>"It turns damp red litmus paper blue.", "difficulty"=>"easy"],
  ["id"=>421, "topic"=>"Introduction to Bases", "question"=>"Write the ionic equation for the reaction between an alkali and an ammonium ion.", "answer"=>"NH4+(aq) + OH-(aq) -> NH3(g) + H2O(l)", "difficulty"=>"hard"],
  ["id"=>422, "topic"=>"Introduction to Bases", "question"=>"What is observed when sodium hydroxide solution is added to a copper(II) sulphate solution?", "answer"=>"A pale blue precipitate of copper(II) hydroxide forms.", "difficulty"=>"medium"],
  ["id"=>423, "topic"=>"Introduction to Bases", "question"=>"Write the ionic equation for the formation of a copper(II) hydroxide precipitate.", "answer"=>"Cu2+(aq) + 2OH-(aq) -> Cu(OH)2(s)", "difficulty"=>"medium"],
  ["id"=>424, "topic"=>"Indicators and pH", "question"=>"State the color of litmus indicator in acidic and alkaline solutions.", "answer"=>"Acidic: Red; Alkaline: Blue.", "difficulty"=>"easy"],
  ["id"=>425, "topic"=>"Indicators and pH", "question"=>"State the color of methyl orange indicator in acidic and alkaline solutions.", "answer"=>"Acidic: Red; Alkaline: Yellow. (End point: Orange)", "difficulty"=>"medium"],
  ["id"=>426, "topic"=>"Indicators and pH", "question"=>"State the color of phenolphthalein indicator in acidic and alkaline solutions.", "answer"=>"Acidic: Colorless; Alkaline: Pink.", "difficulty"=>"easy"],
  ["id"=>427, "topic"=>"Indicators and pH", "question"=>"Define pH mathematically.", "answer"=>"pH = -log10[H+(aq)]", "difficulty"=>"medium"],
  ["id"=>428, "topic"=>"Indicators and pH", "question"=>"Calculate the pH of a 0.01 mol/dm3 solution of Hydrochloric acid (HCl).", "answer"=>"[H+] = 0.01. pH = -log(0.01) = 2.0", "difficulty"=>"medium"],
  ["id"=>429, "topic"=>"Indicators and pH", "question"=>"Calculate the pH of a 0.005 mol/dm3 solution of Sulphuric acid (H2SO4).", "answer"=>"H2SO4 is dibasic, so [H+] = 2 * 0.005 = 0.01. pH = -log(0.01) = 2.0", "difficulty"=>"hard"],
  ["id"=>430, "topic"=>"Indicators and pH", "question"=>"What instrument is used to measure pH accurately without subjective color error?", "answer"=>"A pH meter.", "difficulty"=>"easy"],
  ["id"=>431, "topic"=>"Acid-Base Strength", "question"=>"Define a strong acid.", "answer"=>"An acid that completely ionizes or dissociates in water to release H+ ions.", "difficulty"=>"medium"],
  ["id"=>432, "topic"=>"Acid-Base Strength", "question"=>"Define a weak acid.", "answer"=>"An acid that only partially ionizes or dissociates in water to release H+ ions.", "difficulty"=>"medium"],
  ["id"=>433, "topic"=>"Acid-Base Strength", "question"=>"Give an example of a weak acid and write its dissociation equation.", "answer"=>"Ethanoic acid: CH3COOH(aq) <=> CH3COO-(aq) + H+(aq)", "difficulty"=>"hard"],
  ["id"=>434, "topic"=>"Acid-Base Strength", "question"=>"Define a strong alkali.", "answer"=>"An alkali that completely dissociates in water to release OH- ions.", "difficulty"=>"medium"],
  ["id"=>435, "topic"=>"Acid-Base Strength", "question"=>"Define a weak alkali.", "answer"=>"An alkali that only partially ionizes in water to produce OH- ions.", "difficulty"=>"medium"],
  ["id"=>436, "topic"=>"Acid-Base Strength", "question"=>"Give an example of a weak alkali and write its dissociation equation.", "answer"=>"Aqueous ammonia: NH3(aq) + H2O(l) <=> NH4+(aq) + OH-(aq)", "difficulty"=>"hard"],
  ["id"=>437, "topic"=>"Acid-Base Strength", "question"=>"Explain why 1M HCl reacts faster with magnesium than 1M CH3COOH.", "answer"=>"HCl is a strong acid with a higher concentration of H+ ions, leading to a higher frequency of effective collisions.", "difficulty"=>"hard"],
  ["id"=>438, "topic"=>"Acid-Base Strength", "question"=>"How can you compare the strength of two acids experimentally without running a reaction?", "answer"=>"By measuring their electrical conductivity; the strong acid will exhibit higher electrical conductivity due to its higher ion concentration.", "difficulty"=>"hard"],
  ["id"=>439, "topic"=>"Salts and Neutralization", "question"=>"Define neutralization.", "answer"=>"The reaction between an acid and a base to form a salt and water only.", "difficulty"=>"easy"],
  ["id"=>440, "topic"=>"Salts and Neutralization", "question"=>"Write the net ionic equation for any neutralization reaction between a strong acid and a strong alkali.", "answer"=>"H+(aq) + OH-(aq) -> H2O(l)", "difficulty"=>"medium"],
  ["id"=>441, "topic"=>"Salts and Neutralization", "question"=>"Is neutralization an exothermic or endothermic reaction?", "answer"=>"Exothermic (releases heat).", "difficulty"=>"easy"],
  ["id"=>442, "topic"=>"Salts and Neutralization", "question"=>"State the solubility rule for all Nitrate (NO3-) salts.", "answer"=>"All nitrates are soluble in water.", "difficulty"=>"easy"],
  ["id"=>443, "topic"=>"Salts and Neutralization", "question"=>"State the solubility rule for Group I and Ammonium salts.", "answer"=>"All salts of Group I elements (Na+, K+, etc.) and Ammonium (NH4+) are soluble.", "difficulty"=>"easy"],
  ["id"=>444, "topic"=>"Salts and Neutralization", "question"=>"Name three common insoluble Chloride salts.", "answer"=>"Silver chloride (AgCl), Lead(II) chloride (PbCl2) [soluble in hot water].", "difficulty"=>"medium"],
  ["id"=>445, "topic"=>"Salts and Neutralization", "question"=>"Name three common insoluble Sulphate salts.", "answer"=>"Barium sulphate (BaSO4), Calcium sulphate (CaSO4) [slightly soluble], Lead(II) sulphate (PbSO4).", "difficulty"=>"medium"],
  ["id"=>446, "topic"=>"Salts and Neutralization", "question"=>"What general method is used to prepare an insoluble salt?", "answer"=>"Precipitation (mixing two soluble salt solutions).", "difficulty"=>"medium"],
  ["id"=>447, "topic"=>"Salts and Neutralization", "question"=>"What two soluble solutions could you mix to prepare barium sulphate precipitate?", "answer"=>"Barium chloride solution and Sodium sulphate solution.", "difficulty"=>"medium"],
  ["id"=>448, "topic"=>"Salts and Neutralization", "question"=>"Outline the steps to obtain a pure, dry sample of an insoluble salt from a reaction mixture.", "answer"=>"Filter the mixture, wash the residue with distilled water, and dry it with filter paper or in an oven.", "difficulty"=>"hard"],
  ["id"=>449, "topic"=>"Salts and Neutralization", "question"=>"What general method is used to prepare a soluble salt from an acid and a soluble base/alkali?", "answer"=>"Titration followed by crystallization.", "difficulty"=>"medium"],
  ["id"=>450, "topic"=>"Salts and Neutralization", "question"=>"What general method is used to prepare a soluble salt from an acid and an insoluble base?", "answer"=>"React the acid with excess insoluble base, filter out the excess base, and crystallize the filtrate.", "difficulty"=>"hard"],
  ["id"=>451, "topic"=>"Concentration and Volumetric Analysis", "question"=>"Define molarity (M).", "answer"=>"The number of moles of solute dissolved per dm3 of solution (mol/dm3).", "difficulty"=>"easy"],
  ["id"=>452, "topic"=>"Concentration and Volumetric Analysis", "question"=>"State the formula connecting number of moles, molarity, and volume (in cm3).", "answer"=>"Number of moles = (Molarity * Volume) / 1000", "difficulty"=>"easy"],
  ["id"=>453, "topic"=>"Concentration and Volumetric Analysis", "question"=>"Calculate the number of moles of solute in 25.0 cm3 of 2.0 M NaOH.", "answer"=>"(2.0 * 25.0) / 1000 = 0.05 moles.", "difficulty"=>"easy"],
  ["id"=>454, "topic"=>"Concentration and Volumetric Analysis", "question"=>"How do you convert concentration from mol/dm3 to g/dm3?", "answer"=>"Multiply the molar concentration by the molar mass of the solute.", "difficulty"=>"medium"],
  ["id"=>455, "topic"=>"Concentration and Volumetric Analysis", "question"=>"What is a standard solution?", "answer"=>"A solution of accurately known concentration.", "difficulty"=>"medium"],
  ["id"=>456, "topic"=>"Concentration and Volumetric Analysis", "question"=>"Name a primary standard substance commonly used to standardize acids.", "answer"=>"Anhydrous sodium carbonate (Na2CO3).", "difficulty"=>"hard"],
  ["id"=>457, "topic"=>"Concentration and Volumetric Analysis", "question"=>"What piece of glassware is used to deliver a precise fixed volume (e.g., 25.0 cm3) of solution?", "answer"=>"A pipette.", "difficulty"=>"easy"],
  ["id"=>458, "topic"=>"Concentration and Volumetric Analysis", "question"=>"What piece of glassware is used to deliver a variable volume of solution during titration?", "answer"=>"A burette.", "difficulty"=>"easy"],
  ["id"=>459, "topic"=>"Concentration and Volumetric Analysis", "question"=>"Why should a conical flask be washed only with distilled water and not the solution it will contain?", "answer"=>"Washing with the solution would add extra unmeasured moles of reactant, leading to a titration error.", "difficulty"=>"hard"],
  ["id"=>460, "topic"=>"Concentration and Volumetric Analysis", "question"=>"Why must a burette be rinsed with the solution it will hold before titration?", "answer"=>"To prevent water remaining in the burette from diluting the solution and causing an inaccurate volume reading.", "difficulty"=>"hard"],
  ["id"=>461, "topic"=>"Concentration and Volumetric Analysis", "question"=>"What are concordant titres in a volumetric titration analysis?", "answer"=>"Titre values that are within 0.10 cm3 of each other.", "difficulty"=>"medium"],
  ["id"=>462, "topic"=>"Introduction to Acids", "question"=>"What is the chemical difference between a concentrated acid and a strong acid?", "answer"=>"Concentrated refers to a large amount of solute per unit volume; strong refers to complete dissociation into ions in water.", "difficulty"=>"hard"],
  ["id"=>463, "topic"=>"Concentration and Volumetric Analysis", "question"=>"25.0 cm3 of HCl requires 20.0 cm3 of 0.1M NaOH for neutralization. Calculate the molarity of the HCl.", "answer"=>"Moles of NaOH = 0.002. Mole ratio is 1:1, so Molarity of HCl = 0.002 / 0.025 = 0.08 M.", "difficulty"=>"medium"],
  ["id"=>464, "topic"=>"Introduction to Bases", "question"=>"Are all metal oxides bases? Give examples.", "answer"=>"Yes, metal oxides are basic (or amphoteric), such as MgO and CuO.", "difficulty"=>"medium"],
  ["id"=>465, "topic"=>"Introduction to Bases", "question"=>"Name a household cleaning agent that contains a weak alkali.", "answer"=>"Glass cleaners containing aqueous ammonia.", "difficulty"=>"easy"],
  ["id"=>466, "topic"=>"Salts and Neutralization", "question"=>"What color is solid copper(II) carbonate?", "answer"=>"Green.", "difficulty"=>"easy"],
  ["id"=>467, "topic"=>"Salts and Neutralization", "question"=>"What salt is formed when copper(II) oxide reacts with nitric acid?", "answer"=>"Copper(II) nitrate.", "difficulty"=>"easy"],
  ["id"=>468, "topic"=>"Salts and Neutralization", "question"=>"State a practical application of neutralization in agriculture.", "answer"=>"Adding slaked lime [Ca(OH)2] to acidic soil to neutralize it.", "difficulty"=>"medium"],
  ["id"=>469, "topic"=>"Salts and Neutralization", "question"=>"How does an antacid tablet relieve stomach ache?", "answer"=>"It contains bases like Mg(OH)2 or CaCO3 that neutralize excess hydrochloric acid in the stomach.", "difficulty"=>"medium"],
  ["id"=>470, "topic"=>"Introduction to Acids", "question"=>"What is formed when concentrated sulphuric acid is added to sugar?", "answer"=>"A black spongy mass of carbon (due to its strong dehydrating property).", "difficulty"=>"hard"],
  ["id"=>471, "topic"=>"Introduction to Acids", "question"=>"Why should water never be poured directly into concentrated sulphuric acid during dilution?", "answer"=>"The process is highly exothermic, and the localized heat can cause the water to boil instantly, splashing the corrosive acid.", "difficulty"=>"hard"],
  ["id"=>472, "topic"=>"Introduction to Acids", "question"=>"What is the correct procedure for diluting concentrated sulphuric acid safely?", "answer"=>"Add the concentrated acid slowly down the side of the container into a large volume of water while stirring continuously.", "difficulty"=>"hard"],

