  ["id"=>501, "topic"=>"Fossil Fuels", "question"=>"What are the three main fossil fuels?", "answer"=>"Natural gas, petroleum (crude oil), and coal.", "difficulty"=>"easy"],
  ["id"=>502, "topic"=>"Fossil Fuels", "question"=>"How are fossil fuels formed?", "answer"=>"From large quantities of dead marine organisms buried under sedimentary rock and subjected to intense heat and pressure over a long time.", "difficulty"=>"easy"],
  ["id"=>503, "topic"=>"Fossil Fuels", "question"=>"What is a fuel?", "answer"=>"A substance that burns in oxygen, converting stored chemical energy into heat (an exothermic reaction).", "difficulty"=>"easy"],
  ["id"=>504, "topic"=>"Fossil Fuels", "question"=>"What is petroleum (crude oil)?", "answer"=>"A mixture of thousands of hydrocarbons with different molecular sizes.", "difficulty"=>"easy"],
  ["id"=>505, "topic"=>"Fractional Distillation", "question"=>"Why is fractional distillation used on crude oil?", "answer"=>"To separate it into useful fractions based on their different boiling point ranges.", "difficulty"=>"easy"],
  ["id"=>506, "topic"=>"Fractional Distillation", "question"=>"What happens to the vaporized crude oil inside the fractionating tower?", "answer"=>"It rises up the column; as temperature decreases upwards, fractions condense at their respective boiling points.", "difficulty"=>"medium"],
  ["id"=>507, "topic"=>"Fractional Distillation", "question"=>"State the order of the fractions collected from top to bottom.", "answer"=>"Refinery gas, petrol, naphtha, kerosene, diesel oil, fuel oil, lubricating oil, bitumen.", "difficulty"=>"medium"],
  ["id"=>508, "topic"=>"Fractional Distillation", "question"=>"What are the boiling points, color intensities, and viscosities of the fractions at the top of the tower?", "answer"=>"Low boiling points, light colors, low viscosities, and high volatilities.", "difficulty"=>"medium"],
  ["id"=>509, "topic"=>"Fractional Distillation", "question"=>"What are the properties of the fractions at the bottom of the tower?", "answer"=>"High boiling points, dark colors, high viscosities, and low volatilities.", "difficulty"=>"medium"],
  ["id"=>510, "topic"=>"Fractional Distillation", "question"=>"Why do larger hydrocarbon molecules have higher boiling points?", "answer"=>"Larger molecules have a larger surface contact area, leading to stronger intermolecular van der Waals' forces that require more energy to break.", "difficulty"=>"medium"],
  ["id"=>511, "topic"=>"Fractional Distillation", "question"=>"Define volatility.", "answer"=>"The tendency of a substance to vaporize.", "difficulty"=>"easy"],
  ["id"=>512, "topic"=>"Fractional Distillation", "question"=>"Define viscosity.", "answer"=>"The resistance of a fluid to flow.", "difficulty"=>"easy"],
  ["id"=>513, "topic"=>"Fractions & Uses", "question"=>"State the primary use of refinery gas.", "answer"=>"Gaseous fuel for domestic heating and cooking.", "difficulty"=>"easy"],
  ["id"=>514, "topic"=>"Fractions & Uses", "question"=>"State the primary use of petrol (gasoline).", "answer"=>"Fuel for motor cars.", "difficulty"=>"easy"],
  ["id"=>515, "topic"=>"Fractions & Uses", "question"=>"State the primary industrial use of naphtha.", "answer"=>"Raw material (feedstock) for the chemical industry to manufacture plastics and medicines.", "difficulty"=>"medium"],
  ["id"=>516, "topic"=>"Fractions & Uses", "question"=>"State the primary use of kerosene.", "answer"=>"Fuel for jet aircraft.", "difficulty"=>"easy"],
  ["id"=>517, "topic"=>"Fractions & Uses", "question"=>"State the primary use of diesel oil.", "answer"=>"Fuel for heavy vehicles like buses, trucks, and trains.", "difficulty"=>"easy"],
  ["id"=>518, "topic"=>"Fractions & Uses", "question"=>"State the primary use of fuel oil.", "answer"=>"Fuel for ships and power stations.", "difficulty"=>"easy"],
  ["id"=>519, "topic"=>"Fractions & Uses", "question"=>"State the primary use of bitumen.", "answer"=>"Paving road surfaces and roofing waterproofing layers.", "difficulty"=>"easy"],
  ["id"=>520, "topic"=>"Air Pollution", "question"=>"What pollutants are produced by the incomplete combustion of fossil fuels?", "answer"=>"Carbon monoxide (CO) and unburned hydrocarbons/carbon particulates.", "difficulty"=>"medium"],
  ["id"=>521, "topic"=>"Air Pollution", "question"=>"How are nitrogen oxides (NOx) formed in car engines?", "answer"=>"At the high temperatures inside car cylinders, nitrogen and oxygen from the air react together directly.", "difficulty"=>"hard"],
  ["id"=>522, "topic"=>"Air Pollution", "question"=>"How does a catalytic converter work? Give the equation for CO + NO.", "answer"=>"A platinum-rhodium catalyst converts toxic pollutants into harmless gases: 2CO(g) + 2NO(g) -> 2CO2(g) + N2(g).", "difficulty"=>"hard"],
  ["id"=>523, "topic"=>"Air Pollution", "question"=>"What acid rain pollutant is produced by burning coal or low-quality fuel oil containing sulphur?", "answer"=>"Sulphur dioxide (SO2).", "difficulty"=>"medium"],
  ["id"=>524, "topic"=>"Air Pollution", "question"=>"What device is installed in coal power plants to remove SO2 from flue gases?", "answer"=>"Scrubbers (using calcium oxide/limestone slurry).", "difficulty"=>"hard"],
  ["id"=>525, "topic"=>"Homologous Series", "question"=>"What is a hydrocarbon?", "answer"=>"A compound containing carbon and hydrogen atoms only.", "difficulty"=>"easy"],
  ["id"=>526, "topic"=>"Homologous Series", "question"=>"Define a homologous series.", "answer"=>"A series of compounds with the same functional group, sharing similar chemical properties, showing a gradation in physical properties, where each successive member differs by a -CH2- unit.", "difficulty"=>"medium"],
  ["id"=>527, "topic"=>"Homologous Series", "question"=>"What is the general formula for the alkane homologous series?", "answer"=>"CnH2n+2", "difficulty"=>"easy"],
  ["id"=>528, "topic"=>"Homologous Series", "question"=>"What is the general formula for the alkene homologous series?", "answer"=>"CnH2n", "difficulty"=>"easy"],
  ["id"=>529, "topic"=>"Homologous Series", "question"=>"What is the general formula for the alkanol (alcohol) homologous series?", "answer"=>"CnH2n+1OH", "difficulty"=>"medium"],
  ["id"=>530, "topic"=>"Homologous Series", "question"=>"What is the general formula for the alkanoic acid homologous series?", "answer"=>"CnH2n+1COOH (where n can be 0, 1, 2...)", "difficulty"=>"medium"],
  ["id"=>531, "topic"=>"Nomenclature", "question"=>"Name the first 4 straight-chain alkanes.", "answer"=>"Methane (CH4), Ethane (C2H6), Propane (C3H8), Butane (C4H10).", "difficulty"=>"easy"],
  ["id"=>532, "topic"=>"Nomenclature", "question"=>"Give the IUPAC name for a 5-carbon alkane.", "answer"=>"Pentane.", "difficulty"=>"easy"],
  ["id"=>533, "topic"=>"Nomenclature", "question"=>"Give the IUPAC name for CH3CH(CH3)CH2CH3.", "answer"=>"2-methylbutane.", "difficulty"=>"medium"],
  ["id"=>534, "topic"=>"Nomenclature", "question"=>"Give the structural formula and systematic name for the simplest alkene.", "answer"=>"CH2=CH2, Ethene.", "difficulty"=>"easy"],
  ["id"=>535, "topic"=>"Nomenclature", "question"=>"What is the systematic name for CH3CH2CH2OH?", "answer"=>"Propan-1-ol.", "difficulty"=>"medium"],
  ["id"=>536, "topic"=>"Nomenclature", "question"=>"What is the systematic name for CH3COOH?", "answer"=>"Ethanoic acid.", "difficulty"=>"easy"],
  ["id"=>537, "topic"=>"Nomenclature", "question"=>"Define structural isomers.", "answer"=>"Compounds with the same molecular formula but different structural arrangements.", "difficulty"=>"medium"],
  ["id"=>538, "topic"=>"Nomenclature", "question"=>"How many structural isomers does Butane (C4H10) have?", "answer"=>"Two (butane and 2-methylpropane).", "difficulty"=>"medium"],
  ["id"=>539, "topic"=>"Alkanes & Alkenes", "question"=>"What is the difference between saturated and unsaturated hydrocarbons?", "answer"=>"Saturated hydrocarbons contain only single carbon-carbon bonds; unsaturated hydrocarbons contain at least one carbon-carbon double or triple bond.", "difficulty"=>"medium"],
  ["id"=>540, "topic"=>"Alkanes & Alkenes", "question"=>"What type of chemical reaction occurs when an alkane reacts with bromine under UV light?", "answer"=>"Substitution reaction.", "difficulty"=>"medium"],
  ["id"=>541, "topic"=>"Alkanes & Alkenes", "question"=>"State the condition required for the substitution reaction of methane with chlorine.", "answer"=>"Ultraviolet (UV) light.", "difficulty"=>"easy"],
  ["id"=>542, "topic"=>"Alkanes & Alkenes", "question"=>"Describe the observation when methane is mixed with bromine in 1,1,1-trichloroethane under UV light.", "answer"=>"The reddish-brown solution slowly decolorizes, and misty fumes of HBr are formed.", "difficulty"=>"hard"],
  ["id"=>543, "topic"=>"Alkanes & Alkenes", "question"=>"What type of reaction occurs when an alkene reacts with bromine solution?", "answer"=>"Addition reaction.", "difficulty"=>"medium"],
  ["id"=>544, "topic"=>"Alkanes & Alkenes", "question"=>"Describe the observation when ethene gas is bubbled into a solution of bromine in the dark.", "answer"=>"The reddish-brown bromine solution decolorizes rapidly.", "difficulty"=>"easy"],
  ["id"=>545, "topic"=>"Alkanes & Alkenes", "question"=>"Write the chemical equation for the reaction of ethene with bromine.", "answer"=>"CH2=CH2 + Br2 -> CH2Br-CH2Br (1,2-dibromoethane).", "difficulty"=>"medium"],
  ["id"=>546, "topic"=>"Alkanes & Alkenes", "question"=>"What is the observation when ethene reacts with acidified potassium permanganate solution?", "answer"=>"The purple solution decolorizes rapidly, and a colorless diol is formed.", "difficulty"=>"medium"],
  ["id"=>547, "topic"=>"Alkanes & Alkenes", "question"=>"How can you distinguish between an alkane and an alkene sample using a chemical test in the dark?", "answer"=>"Add bromine solution in the dark; the alkene will decolorize it rapidly while the alkane will show no reaction.", "difficulty"=>"medium"],
  ["id"=>548, "topic"=>"Cracking", "question"=>"What is catalytic cracking?", "answer"=>"The process of breaking down long-chain alkanes into smaller, more useful alkanes and alkenes using high temperatures and a catalyst.", "difficulty"=>"medium"],
  ["id"=>549, "topic"=>"Cracking", "question"=>"What catalyst is commonly used in laboratory cracking experiments?", "answer"=>"Broken unglazed porcelain (or aluminium oxide).", "difficulty"=>"medium"],
  ["id"=>550, "topic"=>"Cracking", "question"=>"Why is cracking highly important in the petroleum refinery industry?", "answer"=>"It matches the supply of shorter-chain fractions (like petrol) with high consumer demand and produces alkenes for plastic manufacturing.", "difficulty"=>"hard"],
  ["id"=>551, "topic"=>"Cracking", "question"=>"Why must the delivery tube be removed from the water bath before you stop heating in a cracking experiment?", "answer"=>"To prevent cold water from sucking back into the hot test tube and causing it to crack.", "difficulty"=>"hard"],
  ["id"=>552, "topic"=>"Polymers", "question"=>"Define addition polymerization.", "answer"=>"A reaction where a large number of unsaturated monomer molecules join together to form a polymer chain without eliminating any small molecules.", "difficulty"=>"medium"],
  ["id"=>553, "topic"=>"Polymers", "question"=>"What is a repeating unit?", "answer"=>"The smallest structural unit of a polymer chain that is repeated throughout its length.", "difficulty"=>"easy"],
  ["id"=>554, "topic"=>"Polymers", "question"=>"Name the monomer used to manufacture polypropene.", "answer"=>"Propene.", "difficulty"=>"easy"],
  ["id"=>555, "topic"=>"Polymers", "question"=>"State one common use of polyvinyl chloride (PVC).", "answer"=>"Water pipes, raincoats, or electrical insulation covers.", "difficulty"=>"medium"],
  ["id"=>556, "topic"=>"Polymers", "question"=>"State the common commercial name for polymethyl methacrylate.", "answer"=>"Perspex.", "difficulty"=>"medium"],
  ["id"=>557, "topic"=>"Polymers", "question"=>"State one common property and use of polystyrene.", "answer"=>"Lightweight insulation properties; used for making disposable foam cups and protective packaging packs.", "difficulty"=>"easy"],
  ["id"=>558, "topic"=>"Polymers", "question"=>"Are addition polymers biodegradable? Why?", "answer"=>"No, they are non-biodegradable because their inert carbon-carbon backbone chains cannot be broken down by micro-organisms.", "difficulty"=>"medium"],
  ["id"=>559, "topic"=>"Polymers", "question"=>"State one environmental hazard associated with burning plastic waste.", "answer"=>"It releases toxic gases (e.g., HCl gas from burning PVC).", "difficulty"=>"medium"],
  ["id"=>560, "topic"=>"Polymers", "question"=>"What is a thermoplastic?", "answer"=>"A plastic that softens when heated and can be remolded multiple times.", "difficulty"=>"easy"],
  ["id"=>561, "topic"=>"Polymers", "question"=>"Why can thermoplastics be remolded upon heating?", "answer"=>"They have long polymer chains held together by weak intermolecular forces that break easily when heated, allowing the chains to slide over one another.", "difficulty"=>"hard"],
  ["id"=>562, "topic"=>"Polymers", "question"=>"What type of polymer plastic does not soften on heating and cannot be remolded?", "answer"=>"Thermosetting plastic.", "difficulty"=>"medium"],
  ["id"=>563, "topic"=>"Polymers", "question"=>"Why do thermosetting plastics decompose rather than melt when heated?", "answer"=>"They contain cross-links (covalent bonds) linking the polymer chains together into a rigid network structure.", "difficulty"=>"hard"],
  ["id"=>564, "topic"=>"Polymers", "question"=>"Deduce the monomer structure of Teflon from its repeating unit (-CF2-CF2-).", "answer"=>"CF2=CF2 (Tetrafluoroethene).", "difficulty"=>"medium"],
  ["id"=>565, "topic"=>"Air Pollution", "question"=>"Name the major greenhouse gas produced by burning fossil fuels.", "answer"=>"Carbon dioxide (CO2).", "difficulty"=>"easy"],
  ["id"=>566, "topic"=>"Air Pollution", "question"=>"What is the environmental consequence of excessive carbon dioxide release into the atmosphere?", "answer"=>"Enhanced greenhouse effect leading to global warming and climate change.", "difficulty"=>"medium"],
  ["id"=>567, "topic"=>"Alkanes & Alkenes", "question"=>"Write the chemical equation for the complete combustion of propane.", "answer"=>"C3H8 + 5O2 -> 3CO2 + 4H2O", "difficulty"=>"medium"],
  ["id"=>568, "topic"=>"Polymers", "question"=>"Why does a sample of plastic not have a sharp, fixed melting point?", "answer"=>"It is a mixture of chains with different lengths and molecular masses.", "difficulty"=>"hard"],
  ["id"=>569, "topic"=>"Cracking", "question"=>"Write an equation for the cracking of decane (C10H22) to produce octane and ethene.", "answer"=>"C10H22 -> C8H18 + C2H4", "difficulty"=>"medium"],
  ["id"=>570, "topic"=>"Nomenclature", "question"=>"What is the functional group of alkanoic acids?", "answer"=>"Carboxyl group (-COOH).", "difficulty"=>"easy"],
  ["id"=>571, "topic"=>"Nomenclature", "question"=>"What is the functional group of alkanols?", "answer"=>"Hydroxyl group (-OH).", "difficulty"=>"easy"],
  ["id"=>572, "topic"=>"Fossil Fuels", "question"=>"What are the main constituent elements of petroleum?", "answer"=>"Carbon and hydrogen.", "difficulty"=>"easy"]
];